          "type": "object",
          "description": "Control payload (contents depend on controlIdentifier and ranFunctionIdentifier)"
        }
      },
      "required": ["type", "id", "dAppIdentifier", "ranFunctionIdentifier", "controlIdentifier", "actionData"]
    },

    "releaseMessage": {
      "title": "E3 Release Message",
      "description": "Sent by either dApp or E3 Agent via PUB socket to tear down the E3 connection. Clears all active subscriptions and resets the dApp state. No response or acknowledgement is required; the receiver processes it locally.",
      "direction": "dApp <-> Agent (PUB, bidirectional)",
      "type": "object",
      "properties": {
        "type": { "const": "releaseMessage" },
        "id": { "$ref": "#/definitions/messageId" },
        "dAppIdentifier": { "$ref": "#/definitions/dAppId" }
      },
      "required": ["type", "id", "dAppIdentifier"]
    },

    "messageAck": {
      "title": "Message Acknowledgement",
      "description": "Sent by E3 Agent via PUB socket as acknowledgement for received messages (e.g., dAppControlAction). Matched to the original message via requestId.",
