        "responseCode": { "$ref": "#/definitions/responseCode" },
        "message": {
          "type": "string",
          "description": "Error description when responseCode is negative"
        }
      },
      "required": ["type", "id", "requestId", "dAppIdentifier", "responseCode"]
    }
